/*
 * ccish driver: command line, diagnostics, and the two passes.
 *
 * Usage: ccish [-l] [-i] [-k] [-o output] input.c
 *   -l  print a listing of the generated bytecode
 *   -i  print the IR stream between stages 1 and 2
 *   -k  keep the stream files (output.data, .code, .syms)
 *   -o  output module name (default: input name without ".c").
 *       To run it with plvm, use a lowercase name with no extension.
 *
 * The compiler proper writes three stream files next to the output;
 * then the final pass (link.c) turns them into the module. The stream
 * files are removed afterward, and after any error, unless -k is given.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "ccish.h"

const char *src_name = "";
int src_line;
int opt_list;
int opt_ir;
static int opt_keep;

/* Files to remove if compilation fails: the streams (unless -k) and a
 * partly written module. */
static const char *base_name;
static const char *module_name;

const char *stream_name(const char *base, const char *suffix)
{
    static char buf[300];
    if (strlen(base) + strlen(suffix) >= sizeof(buf))
        fatal("output name too long", NULL);
    strcpy(buf, base);
    strcat(buf, suffix);
    return buf;
}

static void remove_streams(void)
{
    if (base_name && !opt_keep) {
        remove(stream_name(base_name, SUFFIX_DATA));
        remove(stream_name(base_name, SUFFIX_CODE));
        remove(stream_name(base_name, SUFFIX_SYMS));
    }
}

/* Remove partial output after an error. (On ProDOS, open files will
 * need closing first; on the host, removing an open file is fine.) */
static void clean_up(void)
{
    remove_streams();
    if (module_name)
        remove(module_name);
}

static void report(const char *kind, const char *msg, const char *detail)
{
    fflush(stdout);
    if (src_line > 0)
        fprintf(stderr, "%s:%d: %s: %s", src_name, src_line, kind, msg);
    else
        fprintf(stderr, "ccish: %s: %s", kind, msg);
    if (detail)
        fprintf(stderr, " %s", detail);
    fprintf(stderr, "\n");
}

/* Compilation stops at the first error. */
void error(const char *msg, const char *detail)
{
    report("error", msg, detail);
    clean_up();
    exit(1);
}

void fatal(const char *msg, const char *detail)
{
    report("fatal", msg, detail);
    clean_up();
    exit(1);
}

static void usage(void)
{
    fprintf(stderr, "usage: ccish [-l] [-i] [-k] [-o output] input.c\n");
    exit(2);
}

int main(int argc, char **argv)
{
    static char outbuf[256];
    static Bfile src;
    const char *outname = NULL;
    int i;

    for (i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-l"))
            opt_list = 1;
        else if (!strcmp(argv[i], "-i"))
            opt_ir = 1;
        else if (!strcmp(argv[i], "-k"))
            opt_keep = 1;
        else if (!strcmp(argv[i], "-o") && i + 1 < argc)
            outname = argv[++i];
        else if (argv[i][0] == '-' || src_name[0])
            usage();
        else
            src_name = argv[i];
    }
    if (!src_name[0])
        usage();
    if (!outname) {
        size_t n = strlen(src_name);
        if (n < 3 || strcmp(src_name + n - 2, ".c") || n - 2 >= sizeof(outbuf))
            fatal("input name must end in .c, or use -o", NULL);
        memcpy(outbuf, src_name, n - 2);
        outbuf[n - 2] = 0;
        outname = outbuf;
    }

    /* Pass 1: the compiler proper, writing the stream files. */
    if (!bopen(&src, src_name, 0))
        fatal("cannot open", src_name);
    base_name = outname;
    emit_open(outname);
    lex_open(&src);
    parse_program();
    bclose(&src);
    src_line = 0;
    emit_finish();

    /* Pass 2: the final pass, reading only the stream files. */
    module_name = outname;
    link_module(outname, outname);
    module_name = NULL;
    remove_streams();
    return 0;
}
